  1	/**
  2	 * Security tests for the brainstorm server's per-session key.
  3	 *
  4	 * The companion server is reachable by any local browser tab (default loopback
  5	 * bind) and by any host that can route to it (remote `--host 0.0.0.0` bind).
  6	 * A per-session secret key gates every endpoint so that neither a browser
  7	 * confused-deputy nor a direct remote client can read screens/files or inject
  8	 * events into state/events (prompt injection into a live agent session).
  9	 *
 10	 * Auth = a valid `?key=<token>` query param OR a valid session cookie.
 11	 *
 12	 * Uses the `ws` npm package as a test client (test-only dependency).
 13	 */
 14	
 15	const { spawn } = require('child_process');
 16	const http = require('http');
 17	const WebSocket = require('ws');
 18	const fs = require('fs');
 19	const path = require('path');
 20	const assert = require('assert');
 21	
 22	const SERVER_PATH = path.join(__dirname, '../../skills/brainstorming/scripts/server.cjs');
 23	const TEST_PORT = 3335;
 24	const TEST_DIR = '/tmp/brainstorm-auth-test';
 25	const CONTENT_DIR = path.join(TEST_DIR, 'content');
 26	const TOKEN = 'testtoken-0123456789abcdef0123456789abcdef';
 27	const COOKIE_NAME = `brainstorm-key-${TEST_PORT}`;
 28	const EXPECTED_SECURITY_HEADERS = {
 29	  'referrer-policy': 'no-referrer',
 30	  'cache-control': 'no-store',
 31	  'x-frame-options': 'DENY',
 32	  'content-security-policy': "frame-ancestors 'none'",
 33	  'cross-origin-resource-policy': 'same-origin'
 34	};
 35	
 36	function cleanup() {
 37	  if (fs.existsSync(TEST_DIR)) fs.rmSync(TEST_DIR, { recursive: true });
 38	}
 39	
 40	async function sleep(ms) {
 41	  return new Promise(resolve => setTimeout(resolve, ms));
 42	}
 43	
 44	// Raw HTTP GET with optional key query and Cookie header.
 45	function get(pathname, { key, cookie } = {}) {
 46	  const url = `http://localhost:${TEST_PORT}${pathname}` + (key !== undefined ? `?key=${key}` : '');
 47	  const headers = {};
 48	  if (cookie) headers['Cookie'] = cookie;
 49	  return new Promise((resolve, reject) => {
 50	    http.get(url, { headers }, (res) => {
 51	      let data = '';
 52	      res.on('data', chunk => data += chunk);
 53	      res.on('end', () => resolve({ status: res.statusCode, headers: res.headers, body: data }));
 54	    }).on('error', reject);
 55	  });
 56	}
 57	
 58	// Try to open a WebSocket; resolve 'opened' or 'rejected'.
 59	function wsConnect({ key, cookie, origin } = {}) {
 60	  const url = `ws://localhost:${TEST_PORT}/` + (key !== undefined ? `?key=${key}` : '');
 61	  const headers = {};
 62	  if (cookie) headers['Cookie'] = cookie;
 63	  if (origin) headers['Origin'] = origin;
 64	  const opts = Object.keys(headers).length ? { headers } : {};
 65	  const ws = new WebSocket(url, opts);
 66	  return new Promise((resolve) => {
 67	    let settled = false;
 68	    const done = (outcome) => { if (!settled) { settled = true; resolve({ outcome, ws }); } };
 69	    ws.on('open', () => done('opened'));
 70	    ws.on('error', () => done('rejected'));
 71	    ws.on('close', () => done('rejected'));
 72	    setTimeout(() => done('rejected'), 1500);
 73	  });
 74	}
 75	
 76	function startServer() {
 77	  return spawn('node', [SERVER_PATH], {
 78	    env: { ...process.env, BRAINSTORM_PORT: TEST_PORT, BRAINSTORM_DIR: TEST_DIR, BRAINSTORM_TOKEN: TOKEN }
 79	  });
 80	}
 81	
 82	function assertSecurityHeaders(headers) {
 83	  for (const [name, value] of Object.entries(EXPECTED_SECURITY_HEADERS)) {
 84	    assert.strictEqual(headers[name], value, `${name} should be ${value}`);
 85	  }
 86	}
 87	
 88	function runBootstrapScript(html, sessionStorage) {
 89	  const match = html.match(/<script>\n([\s\S]*?)\n<\/script>/);
 90	  assert(match, 'bootstrap response should contain a script block');
 91	  const replacements = [];
 92	  const location = { replace(url) { replacements.push(url); } };
 93	  new Function('sessionStorage', 'location', match[1])(sessionStorage, location);
 94	  return replacements;
 95	}
