 97	async function waitForServer(server) {
 98	  let stdout = '', stderr = '';
 99	  return new Promise((resolve, reject) => {
100	    server.stdout.on('data', (d) => {
101	      stdout += d.toString();
102	      if (stdout.includes('server-started')) resolve({ stdout });
103	    });
104	    server.stderr.on('data', (d) => { stderr += d.toString(); });
105	    server.on('error', reject);
106	    setTimeout(() => reject(new Error(`Server didn't start. stderr: ${stderr}`)), 5000);
107	  });
108	}
109	
110	function serverStartedMessage(out) {
111	  const line = out.trim().split('\n').find(l => l.includes('server-started'));
112	  assert(line, 'server-started JSON should be present');
113	  return JSON.parse(line);
114	}
115	
116	function assertStartedOnExpectedPort(out) {
117	  const msg = serverStartedMessage(out);
118	  assert.strictEqual(
119	    msg.port,
120	    TEST_PORT,
121	    `auth.test.js expected fixed port ${TEST_PORT}, got ${msg.port}; fixed-port tests must not run through fallback`
122	  );
123	  return msg;
124	}
